actions.script:
identityList = []
const accounts = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#UserEmailAccounts').call()
if (ec.message.hasError()) return
const partyId = ec.user.userAccount?.partyId || null
const name = ec.user.userAccount?.userFullName || ec.user.username
me = {userId: ec.user.userId, partyId: partyId, name: name}
defaultValue = null
for (const account of Array.from(accounts.accountList || [])) {
    if (account.isInternal || !account.canSend) continue
    const identities = Array.from(account.identityList || [])
    if (identities.length === 0) identityList.push({value: 'account:' + account.emailAccountId, label: `${account.accountName || account.emailAddress} <${account.emailAddress}>`,
        emailAccountId: account.emailAccountId, emailIdentityId: null, emailAddress: account.emailAddress, displayName: account.accountName ?? null,
        accountName: account.accountName ?? null, signatureHtml: null, signaturePlacementEnumId: null, useForReplies: false, isDefault: true})
    for (const identity of identities) identityList.push({value: 'identity:' + identity.emailIdentityId,
        label: identity.displayName ? `${identity.displayName} <${identity.emailAddress}>` : identity.emailAddress,
        emailAccountId: account.emailAccountId, emailIdentityId: identity.emailIdentityId, emailAddress: identity.emailAddress,
        displayName: identity.displayName ?? null, accountName: account.accountName ?? null, signatureHtml: identity.signatureHtml ?? null,
        signaturePlacementEnumId: identity.signaturePlacementEnumId ?? null, useForReplies: identity.useForReplies === true, isDefault: identity.isDefault === true})
    if (!defaultValue) {
        const mine = identityList.filter((item) => item.emailAccountId === account.emailAccountId)
        defaultValue = (mine.find((item) => item.isDefault) || mine[0]).value
    }
}
const preferred = String(ec.user.getPreference('MAIL_DEFAULT_ACCOUNT') || '').trim()
if (preferred) {
    const mine = identityList.filter((item) => item.emailAccountId === preferred)
    if (mine.length) defaultValue = (mine.find((item) => item.isDefault) || mine[0]).value
}

const MAIL = 'org.moqui.impl.EmailClientServices'
const L = (text) => ec.l10n.localize(text)
const escape = (text) => String(text ?? '').replace(/[<>&"]/g, (ch) => ({'<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;'})[ch])
const splitAddresses = (text) => {
    const out = []
    if (!text) return out
    let current = '', quote = false, angle = 0
    for (const ch of String(text)) {
        if (ch === '"') quote = !quote
        else if (ch === '<' && !quote) angle++
        else if (ch === '>' && !quote && angle > 0) angle--
        else if ((ch === ',' || ch === ';') && !quote && angle === 0) { if (current.trim()) out.push(current.trim()); current = ''; continue }
        current += ch
    }
    if (current.trim()) out.push(current.trim())
    return out.map((entry) => {
        const match = /^(.*)<([^>]+)>\s*$/.exec(entry)
        if (!match) return {address: entry.replace(/^mailto:/i, '').replace(/^"|"$/g, '').trim(), name: null}
        const name = match[1].trim().replace(/^"(.*)"$/, '$1').trim()
        return {address: match[2].trim(), name: name || null}
    })
}
const addressChip = (entry) => ({value: entry.name ? `"${String(entry.name).replace(/"/g, '')}" <${entry.address}>` : entry.address,
    label: entry.name ? `${entry.name} <${entry.address}>` : entry.address, kind: 'address', locked: false})
const toMillis = (value) => value == null || value === '' ? null : (typeof value === 'number' ? value : Number(value))
const dateText = (millis) => millis ? ec.l10n.format(new Date(millis), 'EEE, MMM d, yyyy h:mm a') : ''
const ids = ec.service.sync().name('org.moqui.comms.ComposeServices.get#Identities').call()
if (ec.message.hasError()) return
const identities = Array.from(ids.identityList || [])
const prefUndo = ec.user.getPreference('MAIL_UNDO_SECONDS')
const placement = ec.user.getPreference('MAIL_SIGNATURE_PLACEMENT')
const result = {identityList: identities, fromValue: ids.defaultValue, me: ids.me, to: [], cc: [], bcc: [], subject: '', body: '', quoteHtml: null,
    emailMessageId: null, parentEmailMessageId: null, isForward: false, parentCommEventId: null, replyToSenderOnly: false, contactListId: null,
    contactListName: null, record: null, attachmentList: [], undoSeconds: prefUndo != null && prefUndo !== '' ? Number(prefUndo) : 10,
    signaturePlacement: placement === 'below' ? 'below' : 'above', threadStore: null, threadId: null, kind: 'new'}
const identityFor = (accountId, addresses) => {
    const wanted = new Set(Array.from(addresses || []).map((address) => String(address || '').toLowerCase()))
    const mine = identities.filter((item) => item.emailAccountId === accountId)
    return (mine.find((item) => item.emailAddress && wanted.has(String(item.emailAddress).toLowerCase())) || mine.find((item) => item.isDefault) || mine[0] || null)
}
const myAddresses = new Set(identities.filter((item) => item.emailAddress).map((item) => String(item.emailAddress).toLowerCase()))
if (ec.user.userAccount?.emailAddress) myAddresses.add(String(ec.user.userAccount.emailAddress).toLowerCase())
const headerValue = (headers, name) => {
    let found = null
    for (const line of String(headers || '').split(/\r?\n/)) {
        if (found != null) { if (/^[ \t]/.test(line)) { found += ' ' + line.trim(); continue } break }
        const colon = line.indexOf(':')
        if (colon > 0 && line.substring(0, colon).trim().toLowerCase() === String(name).toLowerCase()) found = line.substring(colon + 1).trim()
    }
    return found
}
// the quoted part of a reply or forward: the message cleaned to the safe set, apart from the editor
const quoteOf = (message, forward) => {
    const fromText = message.fromName ? `${message.fromName} <${message.fromAddress}>` : (message.fromAddress || '')
    const html = message.body && /<[a-z]/i.test(message.body) ? StringUtilities.cleanHtml(message.body)
            : '<p>' + escape(message.bodyText || message.body || '').replace(/\n/g, '<br>') + '</p>'
    if (forward) return `<div class="ironstone-quote"><p>---------- ${escape(L('Forwarded message'))} ---------<br>${escape(L('From'))}: ${escape(fromText)}<br>` +
        `${escape(L('Date'))}: ${escape(dateText(toMillis(message.messageDate)))}<br>${escape(L('Subject'))}: ${escape(message.subject || '')}<br>` +
        `${escape(L('To'))}: ${escape(message.toAddresses || '')}</p>${html}</div>`
    return `<div class="ironstone-quote"><p>${escape(ec.resource.expand('On ${date}, ${name} wrote:', '', {date: dateText(toMillis(message.messageDate)), name: fromText}))}</p>` +
        `<blockquote>${html}</blockquote></div>`
}
const splitQuote = (html) => {
    const text = String(html || '')
    const at = text.indexOf('<div class="ironstone-quote">')
    return at < 0 ? {body: text, quote: null} : {body: text.substring(0, at), quote: text.substring(at)}
}
const threadMessage = (emailId, headers) => {
    const out = ec.service.sync().name(MAIL + '.get#Thread').parameters({emailMessageId: emailId, includeHeaders: headers === true}).requireNewTransaction(true).call()
    if (ec.message.hasError()) return null
    return {thread: out, message: Array.from(out.messageList || []).find((item) => item.emailMessageId === emailId)}
}
const fileList = (emailId) => Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailId)
        .orderBy('emailMessageAttachmentId').list()).map((file) => ({id: file.emailMessageAttachmentId, name: file.fileName || 'attachment',
            size: file.fileSize ?? null, contentType: file.contentType ?? null}))

if (emailMessageId) {
    // a draft of the user's
    const found = threadMessage(emailMessageId, false)
    if (found == null) return
    const draft = found.message
    if (draft.statusId !== 'ES_DRAFT' && !(draft.statusId === 'ES_READY' && draft.sendError)) { ec.message.addError(`Email message ${emailMessageId} is not a draft`); return }
    if (!draft.canSend) { ec.message.addError(`You may not send from email account ${draft.emailAccountId}`); return }
    const identity = (draft.emailIdentityId && identities.find((item) => item.emailIdentityId === draft.emailIdentityId)) || identityFor(draft.emailAccountId, [draft.fromAddress])
    if (identity) result.fromValue = identity.value
    result.to = splitAddresses(draft.toAddresses).map(addressChip)
    result.cc = splitAddresses(draft.ccAddresses).map(addressChip)
    result.bcc = splitAddresses(draft.bccAddresses).map(addressChip)
    result.subject = draft.subject || ''
    const parts = splitQuote(draft.body || (draft.bodyText ? '<p>' + escape(draft.bodyText).replace(/\n/g, '<br>') + '</p>' : ''))
    result.body = parts.body
    result.quoteHtml = parts.quote
    result.emailMessageId = emailMessageId
    result.parentEmailMessageId = draft.parentEmailMessageId
    result.isForward = !!draft.parentEmailMessageId && !draft.inReplyTo
    result.attachmentList = fileList(emailMessageId)
    result.kind = 'draft'
    // the client's own reference of the draft (save#ComposeDraft clientRef), so a client that edits it offline queues its send by it
    const stored = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).selectField('clientRef')
            .selectField('messageDate').disableAuthz().one()
    result.clientRef = stored?.clientRef ?? null
    // the stamp of its last save, which a save from this copy gives back (baseStamp) so one made elsewhere since is not overwritten
    result.draftStamp = stored?.messageDate == null ? null : (typeof stored.messageDate.getTime === 'function' ? stored.messageDate.getTime() : Number(stored.messageDate))
    if (draft.rootEmailMessageId) { result.threadStore = 'email'; result.threadId = draft.rootEmailMessageId }
} else if (replyToEmailMessageId || forwardEmailMessageId) {
    const parentId = replyToEmailMessageId || forwardEmailMessageId
    const forward = !replyToEmailMessageId
    const found = threadMessage(parentId, true)
    if (found == null) return
    const parent = found.message
    const recipients = splitAddresses(parent.toAddresses).concat(splitAddresses(parent.ccAddresses))
    // from the account it came to when the user may send from it, else the default
    const sendable = identities.filter((item) => !item.isInternal && item.emailAccountId === parent.emailAccountId)
    const identity = sendable.length ? identityFor(parent.emailAccountId, recipients.map((entry) => entry.address)) : null
    if (identity) result.fromValue = identity.value
    else if (!identities.some((item) => !item.isInternal)) { ec.message.addError(L('Add a mail account to send email')); return }
    const subjectText = parent.subject || ''
    result.subject = forward ? (/^fwd?:/i.test(subjectText) ? subjectText : 'Fwd: ' + subjectText) : (/^re:/i.test(subjectText) ? subjectText : 'Re: ' + subjectText)
    result.quoteHtml = quoteOf(parent, forward)
    result.parentEmailMessageId = parentId
    result.isForward = forward
    result.threadStore = 'email'
    result.threadId = found.thread.rootEmailMessageId
    if (!forward) {
        const fromMe = myAddresses.has(String(parent.fromAddress || '').toLowerCase())
        const replyTo = splitAddresses(headerValue(parent.headersString, 'Reply-To'))
        const sender = replyTo.length ? replyTo : [{address: parent.fromAddress, name: parent.fromName}]
        const notMe = (entry) => !myAddresses.has(String(entry.address || '').toLowerCase())
        let toList = fromMe ? splitAddresses(parent.toAddresses) : sender
        let ccList = []
        if (replyAll) {
            toList = toList.concat(fromMe ? [] : splitAddresses(parent.toAddresses).filter(notMe))
            ccList = splitAddresses(parent.ccAddresses).filter(notMe)
        }
        const seen = new Set()
        const unique = (list) => list.filter((entry) => { const key = String(entry.address || '').toLowerCase(); if (!key || seen.has(key)) return false; seen.add(key); return true })
        result.to = unique(toList).map(addressChip)
        result.cc = unique(ccList).map(addressChip)
        result.kind = replyAll ? 'replyAll' : 'reply'
    } else {
        // the forward is a draft now, so the files go with it as copies of their own
        if (!identity && !result.fromValue) { ec.message.addError(L('Add a mail account to send email')); return }
        const chosen = identities.find((item) => item.value === result.fromValue)
        if (!chosen || chosen.isInternal) { ec.message.addError(L('Add a mail account to send email')); return }
        const draft = ec.service.sync().name(MAIL + '.save#Draft').parameters({emailAccountId: chosen.emailAccountId, emailIdentityId: chosen.emailIdentityId,
            parentEmailMessageId: parentId, isForward: true, subject: result.subject, body: '<p></p>' + result.quoteHtml}).call()
        if (ec.message.hasError()) return
        const files = []
        for (const file of ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', parentId).list()) {
            if (!file.attachmentLocation || file.isInline === 'Y') continue
            const safe = String(file.fileName || 'attachment').replace(/[\/\\?#%:]/g, '_')
            const location = `dbresource://email/${chosen.emailAccountId}/${draft.emailMessageId}/${files.length + 1}-${safe}`
            try {
                ec.resource.getLocationReference(location).copyFrom(file.attachmentLocation)
                files.push({attachmentLocation: location, fileName: file.fileName, fileSize: file.fileSize, contentType: file.contentType})
            } catch (err) { ec.logger.warn(`Forward of ${parentId}: the file ${file.fileName} was not copied: ${err && err.message ? err.message : err}`) }
        }
        if (files.length) {
            ec.service.sync().name(MAIL + '.save#Draft').parameters({emailMessageId: draft.emailMessageId, attachmentList: files}).call()
            if (ec.message.hasError()) return
        }
        result.emailMessageId = draft.emailMessageId
        result.attachmentList = fileList(draft.emailMessageId)
        result.kind = 'forward'
    }
} else if (replyToCommEventId) {
    ec.message.addError(L('Replies to internal messages are not available here')); return
} else {
    // a new message: mailto-style values, a mailbox to post to
    for (const [field, text] of [['to', to], ['cc', cc], ['bcc', bcc]]) result[field] = splitAddresses(text).filter((entry) => entry.address).map(addressChip)
    if (subject) result.subject = String(subject)
    if (body) result.body = /<[a-z]/i.test(String(body)) ? StringUtilities.cleanHtml(String(body)) : '<p>' + escape(body).replace(/\n/g, '<br>') + '</p>'
    if (contactListId) { ec.message.addError(L('Mailboxes are not available here')); return }
}
// the record chip: one the user sees
if (recordEntity && recordId) {
    const looked = ec.service.sync().name('org.moqui.comms.ChatScreenServices.lookup#Records').parameters({operation: 'info',
        records: [{recordEntityName: recordEntity, recordId: recordId}]}).call()
    ec.message.clearErrors()
    const info = Array.from(looked?.recordList || [])[0]
    if (info && info.visible) result.record = {recordEntityName: info.entity || recordEntity, recordId: recordId, title: info.title || recordId,
        typeLabel: info.typeLabel || null, icon: info.icon || 'sym_o_link', url: info.url || null}
}
compose = result

const cf = ec.entity.conditionFactory
optionList = []
const text = String(term || '').trim()
const max = Math.max(1, Math.min(limit || 12, 50))
const like = (field) => cf.makeCondition(field, 'like', `%${text}%`, false, true)
if (mode === 'internal') return
if (text.length < 1) return
const seen = new Set()
const add = (address, name) => {
    const key = String(address || '').trim().toLowerCase()
    if (!key.includes('@') || seen.has(key)) return
    seen.add(key)
    const clean = name ? String(name).replace(/"/g, '').trim() : null
    optionList.push({value: clean ? `"${clean}" <${String(address).trim()}>` : String(address).trim(), label: clean ? `${clean} <${String(address).trim()}>` : String(address).trim(), kind: 'address'})
}
const userId = ec.user.userId
// users of this system, by name or address
if (optionList.length < max) for (const account of ec.entity.find('moqui.security.UserAccount').condition(cf.makeCondition([like('username'), like('userFullName'),
        like('emailAddress')], 'or')).condition('emailAddress', 'not-equals', null).condition(cf.makeCondition('disabled', 'not-equals', 'Y', true))
        .selectField('emailAddress').selectField('userFullName').limit(max).disableAuthz().list()) add(account.emailAddress, account.userFullName)
// the user's recent correspondents: addresses of the latest mail in the accounts the user reaches
if (optionList.length < max) {
    const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').requireNewTransaction(true).call()
    ec.message.clearErrors()
    const accountIds = Array.from(access?.accountList || []).filter((account) => !account.isInternal).map((account) => account.emailAccountId)
    if (accountIds.length) {
        const rows = Array.from(ec.entity.find('moqui.basic.email.EmailMessage').condition('emailAccountId', 'in', accountIds)
                .condition(cf.makeCondition([like('fromAddress'), like('fromName'), like('toAddresses')], 'or'))
                .selectField('fromAddress').selectField('fromName').selectField('toAddresses').orderBy('-messageDate').limit(60).list())
        const lower = text.toLowerCase()
        for (const row of rows) {
            if (optionList.length >= max) break
            if (String(row.fromAddress || '').toLowerCase().includes(lower) || String(row.fromName || '').toLowerCase().includes(lower)) add(row.fromAddress, row.fromName)
            for (const part of String(row.toAddresses || '').split(',')) {
                const match = /^(.*)<([^>]+)>\s*$/.exec(part.trim())
                const address = match ? match[2].trim() : part.trim()
                const name = match ? match[1].trim().replace(/^"(.*)"$/, '$1') : null
                if (address.toLowerCase().includes(lower) || String(name || '').toLowerCase().includes(lower)) add(address, name)
            }
        }
    }
}
// what was typed, when it is an address
if (/^[^\s@<>,]+@[^\s@<>,]+\.[^\s@<>,]+$/.test(text)) add(text, null)
optionList = optionList.slice(0, max)

const cf = ec.entity.conditionFactory
let chips = chipList ? Array.from(chipList) : []
if (!chips.length && chipsJson) { try { chips = JSON.parse(chipsJson) } catch (err) { ec.message.addError('The recipients are not JSON'); return } }
if (!Array.isArray(chips)) chips = []
const addresses = []
partyIdList = []
contactListIdList = []
const seenAddress = new Set()
for (const chip of chips) {
    const value = String((chip && (chip.value ?? chip)) || '').trim()
    const label = String((chip && chip.label) || value)
    if (!value) continue
    if (mode === 'internal' || /^(list|group|party):/.test(value)) {
        ec.message.addError(ec.resource.expand('${name} is not an email address', '', {name: label})); return
    } else {
        const match = /<([^>]+)>/.exec(value)
        const address = (match ? match[1] : value).trim()
        if (!/^[^\s@<>,]+@[^\s@<>,]+$/.test(address)) { ec.message.addError(ec.l10n.localize('Not an email address') + ': ' + label); return }
        const key = address.toLowerCase()
        if (!seenAddress.has(key)) { seenAddress.add(key); addresses.push(value) }
    }
}
addressText = addresses.join(', ')

const ids = ec.service.sync().name('org.moqui.comms.ComposeServices.get#Identities').call()
if (ec.message.hasError()) return
const identity = Array.from(ids.identityList || []).find((item) => item.value === fromValue)
if (!identity || identity.isInternal) { ec.message.addError(ec.l10n.localize('Choose a mail account to send from')); return }
const header = (json) => {
    if (!json) return ''
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('org.moqui.comms.ComposeServices.resolve#Recipients').parameters({chipsJson: json, mode: 'email'}).call()
        if (ec.message.hasError()) {
            if (strict) throw new Error(ec.message.getErrorsString())
            // a draft keeps what it can
            let chips = []
            try { chips = JSON.parse(json) } catch (err) { chips = [] }
            return Array.from(chips).map((chip) => String(chip?.value || '')).filter((value) => value.includes('@') && !value.startsWith('party:')).join(', ')
        }
        return out.addressText || ''
    } finally { if (!strict) ec.message.clearErrors(); ec.message.popErrors() }
}
let toText, ccText, bccText
try { toText = header(toJson); ccText = header(ccJson); bccText = header(bccJson) }
catch (err) { ec.message.addError(err && err.message ? err.message : String(err)); return }
const fullBody = String(body || '') + (quoteHtml ? String(quoteHtml) : '')
const parameters = {emailMessageId: emailMessageId || null, emailAccountId: identity.emailAccountId, emailIdentityId: identity.emailIdentityId,
    toAddresses: toText, ccAddresses: ccText, bccAddresses: bccText, subject: subject ?? '', body: fullBody, bodyText: bodyText || null,
    clientRef: clientRef || null, baseStamp: baseStamp ?? null}
if (!emailMessageId && parentEmailMessageId) { parameters.parentEmailMessageId = parentEmailMessageId; parameters.isForward = isForward }
const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.save#Draft').parameters(parameters).call()
if (ec.message.hasError()) return
emailMessageId = out.emailMessageId
rootEmailMessageId = out.rootEmailMessageId
duplicate = out.duplicate === true
draftStamp = out.draftStamp ?? null
conflict = out.conflict === true
compose = null
if (conflict) compose = ec.service.sync().name('org.moqui.comms.ComposeServices.get#ComposeData').parameter('emailMessageId', emailMessageId).call()?.compose || null

const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').call()
if (ec.message.hasError()) return
const draft = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).one()
if (draft == null || !access.accessMap[draft.emailAccountId]) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
if (access.accessMap[draft.emailAccountId] < 2) { ec.message.addError(`You may not send from email account ${draft.emailAccountId}`); return }
if (!(draft.statusId === 'ES_DRAFT' || (draft.statusId === 'ES_READY' && draft.sendError))) { ec.message.addError(`Email message ${emailMessageId} is not a draft`); return }
emailAccountId = draft.emailAccountId

const files = (Array.isArray(contentFile) ? contentFile : [contentFile]).filter((file) => file != null && typeof file === 'object')
if (uploadId) {
    // a file sent in chunks: read from where the upload joined it
    const sent = ec.service.sync().name('org.moqui.impl.ClientSyncServices.take#Upload').parameter('uploadId', uploadId).call()
    if (ec.message.hasError()) return
    files.push({getName: () => sent.fileName, getSize: () => Number(sent.fileSize || 0), contentType: sent.contentType,
        getInputStream: () => ec.resource.getLocationReference(sent.location).openStream()})
}
if (files.length === 0) { ec.message.addError(ec.l10n.localize('Choose one or more files to attach')); return }
const nameOf = (file) => String(typeof file.getName === 'function' ? file.getName() : (file.name || 'attachment')).split(/[\\/]/).pop()
const sizeOf = (file) => Number(typeof file.getSize === 'function' ? file.getSize() : (file.size || 0))
const typeOf = (file) => String(file.contentType || (typeof file.getContentType === 'function' ? file.getContentType() : '') || '') || null
const safe = (name) => String(name || 'attachment').replace(/[\/\\?#%:*"<>|]/g, '_').substring(0, 120)
const token = () => Math.random().toString(36).substring(2, 10) + Date.now().toString(36)
for (const file of files) if (sizeOf(file) > 25 * 1024 * 1024) { ec.message.addError(ec.resource.expand('${name} is over 25 MB', '', {name: nameOf(file)})); return }
const store = (location, file) => {
    const stream = file.getInputStream()
    try { ec.resource.getLocationReference(location).putStream(stream) } finally { if (stream && stream.close) stream.close() }
}
uploadList = []
if (!emailMessageId && clientRef) {
    const found = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#MessageByClientRef').parameter('clientRef', clientRef).call()
    if (ec.message.hasError()) return
    if (!found.emailMessageId) { ec.message.addError(ec.l10n.localize('No draft has this clientRef') + ': ' + clientRef); return }
    emailMessageId = found.emailMessageId
    if (!found.isDraft) {
        // a retry after the message went: its files as they are
        attachmentList = Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId)
                .orderBy('emailMessageAttachmentId').list()).map((row) => ({id: row.emailMessageAttachmentId, name: row.fileName, size: row.fileSize ?? null,
                    contentType: row.contentType ?? null}))
        return
    }
}
if (emailMessageId) {
    const draft = ec.service.sync().name('org.moqui.comms.ComposeServices.check#DraftAccess').parameter('emailMessageId', emailMessageId).call()
    if (ec.message.hasError()) return
    const existing = Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId).list())
            .map((row) => ({attachmentLocation: row.attachmentLocation, fileName: row.fileName, fileSize: row.fileSize, contentType: row.contentType,
                contentId: row.contentId, isInline: row.isInline}))
    const before = existing.length
    for (const file of files) {
        if (clientRef && existing.some((row) => row.fileName === nameOf(file) && Number(row.fileSize ?? -1) === sizeOf(file))) continue
        const location = `dbresource://email/${draft.emailAccountId}/${emailMessageId}/${token()}-${safe(nameOf(file))}`
        store(location, file)
        existing.push({attachmentLocation: location, fileName: nameOf(file), fileSize: sizeOf(file), contentType: typeOf(file)})
    }
    if (existing.length > before) {
        ec.service.sync().name('org.moqui.impl.EmailClientServices.save#Draft').parameters({emailMessageId: emailMessageId, attachmentList: existing}).call()
        if (ec.message.hasError()) return
    }
    attachmentList = Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId)
            .orderBy('emailMessageAttachmentId').list()).map((row) => ({id: row.emailMessageAttachmentId, name: row.fileName, size: row.fileSize ?? null,
                contentType: row.contentType ?? null}))
    return
}
if (!ec.user.userId) { ec.message.addError('No user'); return }
attachmentList = []
for (const file of files) {
    const location = `dbresource://comms/compose/${ec.user.userId}/${token()}/${safe(nameOf(file))}`
    store(location, file)
    uploadList.push({location: location, name: nameOf(file), size: sizeOf(file), contentType: typeOf(file)})
}

const L = (text) => ec.l10n.localize(text)
uploadList = []; linkList = []; failedList = []; attachmentList = null
const safe = (name) => String(name || 'attachment').replace(/[\/\\?#%:*"<>|]/g, '_').substring(0, 120)
const token = () => Math.random().toString(36).substring(2, 10) + Date.now().toString(36)
let draft = null
let existing = null
if (emailMessageId) {
    draft = ec.service.sync().name('org.moqui.comms.ComposeServices.check#DraftAccess').parameter('emailMessageId', emailMessageId).call()
    if (ec.message.hasError()) return
    existing = Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId).list())
            .map((row) => ({attachmentLocation: row.attachmentLocation, fileName: row.fileName, fileSize: row.fileSize, contentType: row.contentType,
                contentId: row.contentId, isInline: row.isInline}))
} else if (!ec.user.userId) { ec.message.addError('No user'); return }
const before = existing ? existing.length : 0
// each picked item in a transaction of its own for what may be refused (a file the user may not open or share),
// so one refused does not stop the others
const own = (name, parameters) => {
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name(name).parameters(parameters).requireNewTransaction(true).call()
        return ec.message.hasError() ? {why: ec.message.getErrorsString()} : {out: out}
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
for (const item of Array.from(itemList || [])) {
    const label = item && item.path ? String(item.path).split('/').pop() : '?'
    ec.message.pushErrors()
    try {
        if (!item || !item.driveId || !item.path) throw new Error(L('No file chosen'))
        const found = own('org.moqui.impl.FileServices.get#ResourceInfo', {driveId: item.driveId, path: item.path, opened: true})
        if (!found.out || !found.out.resource) throw new Error(found.why || L('File not found'))
        const resource = found.out.resource
        if (resource.isDirectory || (resource.size != null && Number(resource.size) > Number(maxAttachBytes || 26214400))) {
            const made = own('org.moqui.impl.FileServices.share#Resource', {driveId: item.driveId, path: item.path,
                isLink: 'Y', permissionEnumId: 'RspView', linkLabel: L('Sent by email')})
            if (!made.out) throw new Error(resource.isDirectory ? L('A folder is sent as a link, and you may not share this one')
                    : L('Too large to attach, and you may not share it by link'))
            const link = made.out
            linkList.push({name: resource.name, linkPath: link.linkPath, size: resource.size ?? null, isDirectory: resource.isDirectory === true})
            continue
        }
        const location = draft ? `dbresource://email/${draft.emailAccountId}/${emailMessageId}/${token()}-${safe(resource.name)}`
                : `dbresource://comms/compose/${ec.user.userId}/${token()}/${safe(resource.name)}`
        const stream = ec.resource.getLocationReference(resource.location).openStream()
        try { ec.resource.getLocationReference(location).putStream(stream) } finally { if (stream && stream.close) stream.close() }
        const entry = {name: resource.name, size: resource.size ?? null, contentType: resource.contentType ?? null}
        if (draft) existing.push({attachmentLocation: location, fileName: resource.name, fileSize: resource.size ?? null, contentType: resource.contentType ?? null})
        else uploadList.push(Object.assign({location: location}, entry))
    } catch (err) {
        const why = err && err.message ? err.message : String(err)
        ec.logger.warn(`Attach from Files: ${label} not attached: ${why}`)
        failedList.push({name: label, error: why})
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
if (draft) {
    if (existing.length > before) {
        ec.service.sync().name('org.moqui.impl.EmailClientServices.save#Draft').parameters({emailMessageId: emailMessageId, attachmentList: existing}).call()
        if (ec.message.hasError()) return
    }
    attachmentList = Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId)
            .orderBy('emailMessageAttachmentId').list()).map((row) => ({id: row.emailMessageAttachmentId, name: row.fileName, size: row.fileSize ?? null,
                contentType: row.contentType ?? null}))
}

ec.service.sync().name('org.moqui.comms.ComposeServices.check#DraftAccess').parameter('emailMessageId', emailMessageId).call()
if (ec.message.hasError()) return
const rows = Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId).list())
const gone = rows.find((row) => row.emailMessageAttachmentId === emailMessageAttachmentId)
if (!gone) { ec.message.addError(ec.l10n.localize('Attachment not found') + ': ' + emailMessageAttachmentId); return }
const kept = rows.filter((row) => row !== gone).map((row) => ({attachmentLocation: row.attachmentLocation, fileName: row.fileName, fileSize: row.fileSize,
    contentType: row.contentType, contentId: row.contentId, isInline: row.isInline}))
ec.service.sync().name('org.moqui.impl.EmailClientServices.save#Draft').parameters({emailMessageId: emailMessageId, attachmentList: kept}).call()
if (ec.message.hasError()) return
if (String(gone.attachmentLocation || '').startsWith(`dbresource://email/`)) {
    try { ec.resource.getLocationReference(gone.attachmentLocation).delete() }
    catch (err) { ec.logger.warn(`The file ${gone.attachmentLocation} was not deleted: ${err}`) }
}
attachmentList = Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId)
        .orderBy('emailMessageAttachmentId').list()).map((row) => ({id: row.emailMessageAttachmentId, name: row.fileName, size: row.fileSize ?? null,
            contentType: row.contentType ?? null}))

const L = (text) => ec.l10n.localize(text)
communicationEventIdList = []
sent = false
duplicate = false
conflict = false
compose = null
const partyId = ec.user.userAccount?.partyId || null
if (recordEntity && recordId) { ec.message.addError(L('Filing mail on a record is not available here')); return }
if (fromValue === 'internal') { ec.message.addError(L('Internal messages are not available here')); return }
if (fromValue !== 'internal') {
    mode = 'email'
    const saved = ec.service.sync().name('org.moqui.comms.ComposeServices.save#ComposeDraft').parameters({emailMessageId: emailMessageId, fromValue: fromValue,
        toJson: toJson, ccJson: ccJson, bccJson: bccJson, subject: subject, body: body, bodyText: bodyText, quoteHtml: quoteHtml,
        parentEmailMessageId: parentEmailMessageId, isForward: isForward, strict: true, clientRef: clientRef || null, baseStamp: baseStamp ?? null}).call()
    if (ec.message.hasError()) return
    emailMessageId = saved.emailMessageId
    if (saved.conflict === true) {
        // saved elsewhere since the client's copy: not sent; the client keeps its own as a copy
        conflict = true
        compose = saved.compose || null
        message = L('Changed elsewhere since: not sent')
        return
    }
    if (saved.duplicate === true) {
        // a retry of a send that went through: its state as it is now, and nothing else is done
        const state = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#SendState').parameter('emailMessageId', emailMessageId).call()
        if (ec.message.hasError()) return
        duplicate = true
        statusId = state.statusId; sent = state.sent === true; sendError = state.sendError ?? null
        scheduledSendDate = state.scheduledSendDate ?? null; message = state.message
        return
    }
    const hold = scheduledSendDate != null ? null : Math.max(0, Math.min(Number(holdSeconds || 0), 300))
    const parameters = {emailMessageId: emailMessageId, scheduledSendDate: scheduledSendDate, holdSeconds: hold}
    const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.send#Draft').parameters(parameters).call()
    if (ec.message.hasError()) return
    statusId = out.statusId
    sent = out.sent === true
    sendError = out.sendError ?? null
    scheduledSendDate = out.scheduledSendDate ?? null
    message = statusId === 'ES_SCHEDULED' ? (hold ? L('Sending…') : L('Scheduled')) : (sent ? L('Sent') : (sendError ? L('Not sent yet: it waits in the Outbox') + ' (' + sendError + ')' : L('Sent')))
}
// Send and archive: the thread answered leaves the Inbox
if (archiveThread && threadStore && threadId) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('org.moqui.comms.InboxServices.set#ThreadState').parameters({targetList: [{store: threadStore, threadId: threadId}], action: 'archive'}).call()
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}

if (emailMessageId) {
    const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.cancel#ScheduledSend').parameter('emailMessageId', emailMessageId).call()
    if (ec.message.hasError()) return
    statusId = out.statusId
    return
}
ec.message.addError(ec.l10n.localize('Nothing to undo'))
